css:
.fx-nm{width:100%;max-width:100%}
.nm-sec{--k:0;position:relative}
.nm-stage{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(1.5em,5vw,4em);align-items:center;padding:clamp(2em,6vw,4em) clamp(1em,6vw,4em);background:var(--surface);overflow:hidden}
.nm-copy{display:grid;gap:.6em;align-content:center}
.nm-eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.nm-num{display:flex;align-items:baseline;gap:.1em;font:800 clamp(4.4em,15vw,9.5em)/.95 var(--font-heading);letter-spacing:-.04em;font-variant-numeric:tabular-nums;color:var(--primary)}
.nm-num small{font-size:.4em;color:var(--accent);letter-spacing:0}
.nm-labels{display:grid}.nm-l{grid-area:1/1;margin:0;font-size:clamp(1.1em,2.4vw,1.5em);max-width:16em;opacity:var(--v,1)}
.nm-l:not(:first-child){opacity:var(--v,0)}
.nm-svg{width:min(100%,62svh);aspect-ratio:1;justify-self:center;display:block;overflow:visible}
.nm-svg polygon{fill:color-mix(in srgb,var(--ca,var(--primary)) calc((1 - var(--k))*100%),var(--cb,var(--accent)));stroke:none}
.nm-dots{display:none}
.nm-on .nm-sec{height:calc(var(--n)*100svh + 60svh)}
.nm-on .nm-stage{position:sticky;top:0;height:100svh;min-height:520px}
.nm-on .nm-dots{display:flex;gap:.5em;position:absolute;left:clamp(1em,6vw,4em);bottom:clamp(1em,5svh,2.2em)}
.nm-dots i{width:.7em;height:.7em;border-radius:50%;background:var(--border);transition:background calc(.3s/var(--speed)),transform calc(.3s/var(--speed))}
.nm-dots i.on{background:var(--accent);transform:scale(1.4)}
@media(max-width:700px){.nm-stage{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto;align-content:center;gap:1em}.nm-svg{order:-1;width:min(70%,36svh)}.nm-copy{justify-items:start}}

